    if cur.get("tunnel") or cur.get("inside"):
        return "player tunnel=%s inside=%s" % (cur.get("tunnel", False), cur.get("inside", False))
    return None

def check(prev, cur, ctx):
    if not cur.get("visible", True):
        return None
    vy = cur.get("vy", 0)
    pvy = prev.get("vy", 0)
    is_jump = vy < -600 and (vy - pvy) < -300
    if is_jump:
        mem = ctx["mem"]
        air_jumps = mem.get("air_jumps", 0)
        if prev.get("floor", False):
            mem["air_jumps"] = 0
        else:
            if air_jumps >= ctx.get("max_air_jumps", 1):
                return "air jumps %d > allowed %d" % (air_jumps + 1, ctx.get("max_air_jumps", 1))
            mem["air_jumps"] = air_jumps + 1
    if cur.get("floor", False):
        ctx["mem"]["air_jumps"] = 0
    return None

def check(prev, cur, ctx):
    for ev in ctx.get("events", []):
        if ev.get("type") == "score" and ev.get("from") is not None and ev["to"] - ev["from"] > 1:
            return "score jumped %s -> %s from one pickup" % (ev["from"], ev["to"])
    if ctx.get("score") is not None and ctx.get("start_collectibles", -1) >= 0:
        mem = ctx["mem"]
        if ctx["score"] - ctx["start_score"] > ctx["taken"] + 1:
            mem["over"] = mem.get("over", 0) + 1
            if mem["over"] > 120:
                return "score %s but only %s coins taken" % (ctx["score"], ctx["taken"])
        else:
            mem["over"] = 0
    return None
